class Solution:
    def minOperations(self, nums):
        n = len(nums)
        target = list(range(n))
        best = float('inf')
        cur = nums[:]
        for k in range(n):
            if cur == target:
                best = min(best, k, n - k + 2)
            cur.append(cur.pop(0))
        cur = nums[::-1]
        for j in range(n):
            if cur == target:
                best = min(best, j + 1, n - j + 1)
            cur.append(cur.pop(0))
        return best if best != float('inf') else -1

