public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();
        vector<int> target(n);
        iota(target.begin(), target.end(), 0);
        long long best = LLONG_MAX;
        vector<int> cur = nums;
        for (int k = 0; k < n; k++) {
            if (cur == target) best = min(best, (long long)min(k, n - k + 2));
            rotate(cur.begin(), cur.begin() + 1, cur.end());
        }
        cur = nums;
        reverse(cur.begin(), cur.end());
        for (int j = 0; j < n; j++) {
            if (cur == target) best = min(best, (long long)min(j + 1, n - j + 1));
            rotate(cur.begin(), cur.begin() + 1, cur.end());
        }
        return best == LLONG_MAX ? -1 : (int)best;
    }
};

