class Solution {
    public int minOperations(int[] nums) {
        int n = nums.length;
        int[] target = new int[n];
        for (int i = 0; i < n; i++) target[i] = i;
        long best = Long.MAX_VALUE;
        int[] cur = nums.clone();
        for (int k = 0; k < n; k++) {
            if (Arrays.equals(cur, target)) best = Math.min(best, Math.min(k, n - k + 2));
            int f = cur[0];
            System.arraycopy(cur, 1, cur, 0, n - 1);
            cur[n - 1] = f;
        }
        cur = new int[n];
        for (int i = 0; i < n; i++) cur[i] = nums[n - 1 - i];
        for (int j = 0; j < n; j++) {
            if (Arrays.equals(cur, target)) best = Math.min(best, Math.min(j + 1, n - j + 1));
            int f = cur[0];
            System.arraycopy(cur, 1, cur, 0, n - 1);
            cur[n - 1] = f;
        }
        return best == Long.MAX_VALUE ? -1 : (int) best;
    }
}

