    const n = nums.length;
    const eq = (a) => a.every((v, i) => v === i);
    let best = Infinity;
    let cur = nums.slice();
    for (let k = 0; k < n; k++) {
        if (eq(cur)) best = Math.min(best, k, n - k + 2);
        cur.push(cur.shift());
    }
    cur = nums.slice().reverse();
    for (let j = 0; j < n; j++) {
        if (eq(cur)) best = Math.min(best, j + 1, n - j + 1);
        cur.push(cur.shift());
    }
    return best === Infinity ? -1 : best;
};

