        p = nums.index(0)
        ok_rot = all(nums[(i + p) % n] == i for i in range(n))
        ok_rev = all(nums[n - 1 - ((i + n - 1 - p) % n)] == i for i in range(n))
        best = float('inf')
        if ok_rot:
            best = min(best, p, n - p + 2)
        if ok_rev:
            best = min(best, n - p, p + 1)
        return best if best != float('inf') else -1

