class Solution {
public:
    int minOperations(vector<int>& nums) {
        int n = nums.size();
        int p = find(nums.begin(), nums.end(), 0) - nums.begin();
        bool okRot = true, okRev = true;
        for (int i = 0; i < n; i++) {
            if (nums[(i + p) % n] != i) okRot = false;
            if (nums[n - 1 - ((i + n - 1 - p) % n)] != i) okRev = false;
        }
        long long best = LLONG_MAX;
        if (okRot) best = min({best, (long long)p, (long long)n - p + 2});
        if (okRev) best = min({best, (long long)n - p, (long long)p + 1});
        return best == LLONG_MAX ? -1 : (int)best;
    }
};

