            if (nums[n - 1 - ((i + n - 1 - p) % n)] != i) okRev = false;
        }
        long best = Long.MAX_VALUE;
        if (okRot) best = Math.min(best, Math.min(p, n - p + 2));
        if (okRev) best = Math.min(best, Math.min(n - p, p + 1));
        return best == Long.MAX_VALUE ? -1 : (int) best;
    }
}

